#!/usr/bin/env python3
"""Generate Figures 1 and 2 from their YAML data:
  figures/three_body.yaml    -> figures/three_body.tex
  figures/three_records.yaml -> figures/three_records.tex

Usage (from paper/):  python3 figures/make_reader_figures.py
"""
from pathlib import Path

import yaml

HERE = Path(__file__).resolve().parent


def esc(s: str) -> str:
    return s.replace("&", r"\&").replace("%", r"\%")


def brk(s: str) -> str:
    return esc(s).replace("\\ ", r"\\ ")


def header(extra: str = "") -> list[str]:
    return [
        "% Generated by figures/make_reader_figures.py from the YAML data; do not edit by hand.",
        r"\begin{tikzpicture}[font=\footnotesize, >={Stealth[length=2.2mm]},",
        r"  execute at begin node={\hyphenpenalty=10000\exhyphenpenalty=10000}," + extra,
    ]


def three_body(data) -> str:
    nodes = {n["id"]: n for n in data["nodes"]}
    out = header()
    out += [
        r"  body/.style={draw, very thick, rounded corners=2pt, align=center, text width=2.5cm, minimum height=0.95cm, fill=white},",
        r"  note/.style={align=center, text width=3.4cm, font=\scriptsize\itshape},",
        "]",
    ]

    def tagged(label: str, width: str) -> str:
        *tags, rest = label.split("\\ ")
        tagline = "\\\\[-1pt] ".join(f"\\textbf{{{esc(t)}}}" for t in tags)
        return f"{tagline}\\\\[-1pt] {{\\scriptsize {esc(rest)}}}"

    sys_, pri, cla = (nodes[k] for k in ("sys", "pri", "cla"))
    out.append(f"  \\coordinate (S) at ({sys_['pos'][0]},{sys_['pos'][1]});")
    out.append(f"  \\coordinate (P) at ({pri['pos'][0]},{pri['pos'][1]});")
    out.append(f"  \\coordinate (C) at ({cla['pos'][0]},{cla['pos'][1]});")
    out.append(r"  \fill[black!7] (S) -- (P) -- (C) -- cycle;")
    rel = nodes["rel"]
    out.append(f"  \\node[align=center, text width=3.5cm, font=\\scriptsize] at ({rel['pos'][0]},{rel['pos'][1]}) {{{tagged(rel['label'], '3.5cm')}}};")
    for k in ("sys", "pri", "cla"):
        n = nodes[k]
        out.append(f"  \\node[body] ({k}) at ({n['pos'][0]},{n['pos'][1]}) {{{esc(n['label'])}}};")
    for r in data["relations"]:
        a, b, kind, lab = r["from"], r["to"], r["kind"], r.get("label", "")
        if kind == "authorizes":
            out.append(f"  \\draw[thick] ({a}) -- node[below=6pt, align=center, text width=5.4cm] {{{tagged(lab, '5.4cm')}}} ({b});")
        elif kind == "acts_for":
            out.append(f"  \\draw[thick, ->] ({a}) -- node[pos=0.3, left=3pt, font=\\scriptsize] {{{esc(lab)}}} ({b});")
        else:
            out.append(f"  \\draw[thick, ->] ({a}) -- node[pos=0.3, right=3pt, font=\\scriptsize] {{{esc(lab)}}} ({b});")
    fr = nodes["frame"]
    (x0, y0), (x1, y1) = fr["corner_sw"], fr["corner_ne"]
    tag, _, rest = fr["label"].partition("\\ ")
    out.append(f"  \\draw[dashed, rounded corners=4pt] ({x0},{y0}) rectangle ({x1},{y1});")
    out.append(f"  \\node[anchor=south west, inner sep=1pt] at ({x0 + 0.1},{y1 + 0.02}) "
               f"{{\\textbf{{{esc(tag)}}} {{\\scriptsize {esc(rest)}}}}};")
    n = nodes["who"]
    out.append(f"  \\node[note] at ({n['pos'][0]},{n['pos'][1]}) {{{esc(n['label'])}}};")
    out.append(r"\end{tikzpicture}")
    return "\n".join(out) + "\n"


def three_records(data) -> str:
    nodes = {n["id"]: n for n in data["nodes"]}
    out = header()
    out += [
        r"  record/.style={draw, thick, align=center, text width=3.4cm, minimum height=1.6cm, fill=white, inner sep=4pt},",
        r"  input/.style={align=center, text width=3.4cm, font=\scriptsize\itshape, inner sep=2pt},",
        r"  action/.style={draw, thick, rounded corners=3pt, align=center, text width=3.2cm, inner sep=3pt, fill=white, font=\scriptsize},",
        r"  note/.style={align=center, text width=3.7cm, font=\scriptsize},",
        r"  band/.style={draw, fill=black!8, align=center, inner sep=4pt, font=\footnotesize},",
        r"  tag/.style={draw, black!60, text=black, align=center, text width=3.6cm, minimum height=1.95cm, font=\scriptsize, inner sep=3pt},",
        "]",
    ]
    for n in data["nodes"]:
        k, x, y = n["kind"], n["pos"][0], n["pos"][1]
        if k == "record":
            out.append(f"  \\node[record] ({n['id']}) at ({x},{y}) {{\\textbf{{{esc(n['title'])}}}\\\\ {esc(n['label'])}}};")
        elif k == "band":
            out.append(f"  \\node[band, text width={n['width']}cm] ({n['id']}) at ({x},{y}) {{{esc(n['label'])}}};")
        elif k == "tag" and n.get("width"):
            out.append(f"  \\node[tag, text width={n['width']}cm] ({n['id']}) at ({x},{y}) {{{esc(n['label'])}}};")
        else:
            out.append(f"  \\node[{k}] ({n['id']}) at ({x},{y}) {{{brk(n['label'])}}};")
    for r in data["relations"]:
        a, b, kind, lab = r["from"], r["to"], r["kind"], r.get("label", "")
        if kind == "clears_neither":
            labnode = f" node[pos=0.55, above, sloped, font=\\scriptsize] {{{esc(lab)}}}" if lab else ""
            out.append(f"  \\draw[thick, densely dashed, ->] ({a}) -- node[pos=0.3, font=\\large, fill=white, inner sep=0.5pt] {{$\\times$}}{labnode} ({b});")
        elif kind == "restores":
            out.append(f"  \\draw[thick, ->] ({a}) -- node[right=1pt, font=\\scriptsize] {{{esc(lab)}}} ({b});")
        else:
            out.append(f"  \\draw[thick, ->] ({a}) -- ({b});")
    out.append(r"\end{tikzpicture}")
    return "\n".join(out) + "\n"


def main():
    for name, fn in (("three_body", three_body), ("three_records", three_records)):
        data = yaml.safe_load((HERE / f"{name}.yaml").read_text(encoding="utf-8"))
        (HERE / f"{name}.tex").write_text(fn(data), encoding="utf-8")
        print(f"wrote figures/{name}.tex ({len(data['nodes'])} nodes, {len(data['relations'])} relations)")


if __name__ == "__main__":
    main()
